def has_close_elements(numbers: List[float], threshold: float) -> bool:
    if len(numbers) <= 1:
        return False
    sorted_nums = sorted(numbers)
    for i in range(len(sorted_nums) - 1):
        if sorted_nums[i + 1] - sorted_nums[i] < threshold:
            return True
    return False

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        return 0.0
    mean = sum(numbers) / len(numbers)
    total_abs_diff = sum(abs(x - mean) for x in numbers)
    return total_abs_diff / len(numbers)

def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build grid with 1-based indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    INF_NEG = -10**15
    # dp_prev[x1][x2] for previous step k-1
    dp_prev = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # The number of steps from (1,1) to (N,N) is 2N-2
    for k in range(1, 2 * N - 1):
        dp_curr = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
        sum_xy = k + 2  # because at step k, x1 + y1 = sum_xy
        for x1 in range(1, N + 1):
            y1 = sum_xy - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(1, N + 1):
                y2 = sum_xy - x2
                if y2 < 1 or y2 > N:
                    continue
                best_prev = INF_NEG
                # consider four possible moves for each path
                for dx1 in (0, 1):
                    for dx2 in (0, 1):
                        prev_x1 = x1 - dx1
                        prev_x2 = x2 - dx2
                        if prev_x1 < 1 or prev_x2 < 1:
                            continue
                        val = dp_prev[prev_x1][prev_x2]
                        if val > best_prev:
                            best_prev = val
                if best_prev == INF_NEG:
                    continue
                if x1 == x2 and y1 == y2:
                    total = best_prev + grid[x1][y1]
                else:
                    total = best_prev + grid[x1][y1] + grid[x2][y2]
                dp_curr[x1][x2] = total
        dp_prev = dp_curr

    return dp_prev[N][N] if dp_prev[N][N] != INF_NEG else 0

