def count_passing_ways(n: int, m: int) -> int:
    from math import comb
    total = 0
    # net displacement k ranges from -m to m in steps of 2 (parity must match m)
    for k in range(-m, m + 1, 2):
        if k % n == 0:
            # number of sequences with net k: choose (m + k)/2 steps to the right
            total += comb(m, (m + k) // 2)
    return total

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    """
    0-1 knapsack variant maximizing total price * importance.
    """
    dp = [0] * (n + 1)
    for price, importance in items:
        value = price * importance
        for w in range(n, price - 1, -1):
            new_val = dp[w - price] + value
            if new_val > dp[w]:
                dp[w] = new_val
    return max(dp)

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    first = True
    for i, coeff in enumerate(coeffs):
        deg = n - i
        if coeff == 0:
            continue
        # Determine sign
        if first:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coef = abs(coeff)
        # Coefficient part
        if abs_coef == 1 and deg != 0:
            coef_str = ''
        else:
            coef_str = str(abs_coef)
        # Variable part
        if deg == 0:
            var_str = ''
        elif deg == 1:
            var_str = 'x'
        else:
            var_str = f'x^{deg}'
        term = f'{sign}{coef_str}{var_str}'
        terms.append(term)
        first = False
    if not terms:
        return '0'
    return ''.join(terms)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque
    if A == B:
        return 0
    seen = {A}
    q = deque([(A, 0)])
    max_steps = 10
    while q:
        curr, step = q.popleft()
        if step >= max_steps:
            continue
        new_step = step + 1
        for src, tgt in rules:
            start = 0
            while True:
                i = curr.find(src, start)
                if i == -1:
                    break
                new_s = curr[:i] + tgt + curr[i+len(src):]
                if new_s == B:
                    return new_step
                if new_s not in seen:
                    seen.add(new_s)
                    q.append((new_s, new_step))
                start = i + 1
    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    start = str(n)
    visited = {start}
    queue = [start]
    rule_map = {}
    for x, y in rules:
        dx = str(x)
        dy = str(y)
        if dx in rule_map:
            rule_map[dx].append(dy)
        else:
            rule_map[dx] = [dy]
    i = 0
    while i < len(queue):
        cur = queue[i]
        i += 1
        for pos, digit in enumerate(cur):
            if digit in rule_map:
                for new_digit in rule_map[digit]:
                    new_num = cur[:pos] + new_digit + cur[pos + 1 :]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)
    return len(visited)

def calculate_score(system: int, points: str) -> list:
    result = []
    player_score = opponent_score = 0
    for event in points:
        if event == 'W':
            player_score += 1
        elif event == 'L':
            opponent_score += 1
        else:
            # Ignore any other characters
            continue
        # Check if the game is finished
        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            result.append(f"{player_score}:{opponent_score}")
            player_score = opponent_score = 0
    # Add unfinished game score if any points were played
    if player_score > 0 or opponent_score > 0:
        result.append(f"{player_score}:{opponent_score}")
    return result

