def max_herb_value(T: int, M: int, herbs: list[tuple[int, int]]) -> int:
    # 0/1 Knapsack DP. dp[t] = maximum value achievable with exactly t time
    # We only need dp of size T+1, initialized to 0.
    dp = [0] * (T + 1)
    for time_req, value in herbs:
        if time_req > T:
            continue  # cannot pick this herb
        # iterate backwards to avoid reusing the same herb
        for t in range(T, time_req - 1, -1):
            new_val = dp[t - time_req] + value
            if new_val > dp[t]:
                dp[t] = new_val
    # the answer is the maximum value achievable with time <= T
    return max(dp)

def calculate_arrangements(n, m, a):
    MOD = 10**6 + 7
    dp = [0] * (m + 1)
    dp[0] = 1
    for i in range(n):
        limit = a[i]
        # Prefix sums of current dp
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for s in range(1, m + 1):
            prefix[s] = (prefix[s - 1] + dp[s]) % MOD
        new_dp = [0] * (m + 1)
        for s in range(m + 1):
            low = s - limit
            if low <= 0:
                new_dp[s] = prefix[s]
            else:
                new_dp[s] = (prefix[s] - prefix[low - 1]) % MOD
        dp = new_dp
    return dp[m] % MOD

def find_most_unhappy_day(schedule) -> int:
    max_surplus = -1
    day_of_max = 0
    for idx, (school, extra) in enumerate(schedule, start=1):
        total = school + extra
        if total > 8:
            surplus = total - 8
            if surplus > max_surplus:
                max_surplus = surplus
                day_of_max = idx
    return day_of_max if max_surplus != -1 else 0

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n == 0:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Maximum length of a bitonic subsequence
    max_bitonic = 0
    for i in range(n):
        max_bitonic = max(max_bitonic, lis[i] + lds[i] - 1)

    return n - max_bitonic

